import { randomUUID } from 'node:crypto';import { z } from 'zod';import { getDb } from '../../../../lib/db';import { getSession } from '../../../../lib/session';import { jsonError,jsonOk,readJson } from '../../../../lib/http';
const schema=z.object({name:z.string().trim().min(3).max(220),categoryId:z.string().uuid(),brand:z.string().max(120).optional().default(''),sku:z.string().max(100).optional().default(''),description:z.string().trim().min(10).max(5000),price:z.number().positive().max(100000000),stock:z.number().int().min(0).max(10000000),imageUrl:z.url().max(1000).optional().or(z.literal('')).default(''),isWholesale:z.boolean().default(false),minimumOrderQuantity:z.number().int().min(1).max(100000).default(1)});
export async function GET(){const user=await getSession();if(!user)return jsonError('Please sign in.',401);if(user.role!=='VENDOR'&&user.role!=='ADMIN')return jsonError('Vendor access required.',403);try{const db=getDb();const [rows]=user.role==='ADMIN'?await db.execute('SELECT p.*,v.business_name,c.name AS category_name FROM products p JOIN vendors v ON v.id=p.vendor_id JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC LIMIT 200'):await db.execute('SELECT p.*,c.name AS category_name FROM products p JOIN vendors v ON v.id=p.vendor_id JOIN categories c ON c.id=p.category_id WHERE v.user_id=? ORDER BY p.created_at DESC LIMIT 200',[user.id]);return jsonOk({products:rows});}catch(e){console.error('Products error:',e);return jsonError('Could not load products.',500);}}
export async function POST(request){const user=await getSession();if(!user)return jsonError('Please sign in.',401);if(user.role!=='VENDOR')return jsonError('Vendor access required.',403);const parsed=schema.safeParse(await readJson(request));if(!parsed.success)return jsonError(parsed.error.issues[0]?.message||'Check product details.');try{const db=getDb();const [vs]=await db.execute('SELECT id,approved FROM vendors WHERE user_id=? LIMIT 1',[user.id]);const vendor=vs[0];if(!vendor)return jsonError('Vendor profile not found.',404);if(!vendor.approved)return jsonError('Your vendor account must be approved before you can list products.',403);const slugBase=parsed.data.name.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'').slice(0,190);const id=randomUUID(),slug=`${slugBase}-${id.slice(0,8)}`;const [cats]=await db.execute('SELECT id FROM categories WHERE id=? AND active=1 LIMIT 1',[parsed.data.categoryId]);if(!cats.length)return jsonError('Choose a valid category.');await db.execute('INSERT INTO products (id,vendor_id,category_id,name,slug,brand,sku,description,price,stock,image_url,minimum_order_quantity,is_wholesale,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,\'PENDING\')',[id,vendor.id,parsed.data.categoryId,parsed.data.name,slug,parsed.data.brand||null,parsed.data.sku||null,parsed.data.description,parsed.data.price,parsed.data.stock,parsed.data.imageUrl||null,parsed.data.minimumOrderQuantity,parsed.data.isWholesale?1:0]);return jsonOk({ok:true,id,status:'PENDING'},201);}catch(e){console.error('Product create error:',e);return jsonError('Could not submit product. Please try again.',500);}}
